XMVP.Portions:
[
  {
    "id": 1,
    "duration_sec": 33.36363636363637,
    "content": "[Curtain up]\n[Two people, P & Dr, sit at a round, white, brightly spotlit two-top table in an otherwise empty room with sound dampening baffles hidden behind its thick black wallpaper, as though one is interviewing the other for public access television.]",
    "dialogue": []
  },
  {
    "id": 2,
    "duration_sec": 33.36363636363637,
    "content": "PAT: I want to make a zombie musical.\n[The music starts]",
    "dialogue": [
      {
        "character": "PAT",
        "text": "I want to make a zombie musical.",
        "start_offset": 0.0,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      },
      {
        "character": "PAT",
        "text": "...",
        "start_offset": 2.8000000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 3,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Okay, spooky. Is this for the autumn holiday season?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Okay, spooky. Is this for the autumn holiday season?",
        "start_offset": 3.2,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 4,
    "duration_sec": 33.36363636363637,
    "content": "PAT: No, it's a different thing.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "No, it's a different thing.",
        "start_offset": 6.800000000000001,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 5,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Which?\n[Pause]",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Which?",
        "start_offset": 8.8,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      },
      {
        "character": "DOC",
        "text": "...",
        "start_offset": 9.200000000000001,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 6,
    "duration_sec": 33.36363636363637,
    "content": "PAT: This is all because of a musician.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "This is all because of a musician.",
        "start_offset": 9.600000000000001,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 7,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Ah.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Ah.",
        "start_offset": 12.400000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 8,
    "duration_sec": 33.36363636363637,
    "content": "PAT: One that has forsaken me. Personally.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "One that has forsaken me. Personally.",
        "start_offset": 12.800000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 9,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Oh no! I'm sorry to hear that.\nAnd that's why you want to make this musical?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Oh no! I'm sorry to hear that.",
        "start_offset": 15.200000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      },
      {
        "character": "DOC",
        "text": "And that's why you want to make this musical?",
        "start_offset": 18.000000000000004,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 10,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Online. They're DEAD to me.\nGet it? It's also a comedy.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Online. They're DEAD to me.",
        "start_offset": 21.600000000000005,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      },
      {
        "character": "PAT",
        "text": "Get it? It's also a comedy.",
        "start_offset": 23.600000000000005,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 11,
    "duration_sec": 33.36363636363637,
    "content": "DOC: [Distracted] Let me know.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "[Distracted] Let me know.",
        "start_offset": 26.000000000000007,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 12,
    "duration_sec": 33.36363636363637,
    "content": "PAT: [Eerily focused] Oh, for sure. And that's part of it, currently.\nAnother is because this musician, this artist \u2014 who was already anonymous, as far as I was concerned, before taking the extraordinary step of forsaking me, limiting my access to existing and future content, eternally, online \u2014 doesn't make enough of their music. So, without a doubt, I want to hear more music like that.\n[Pause]",
    "dialogue": [
      {
        "character": "PAT",
        "text": "[Eerily focused] Oh, for sure. And that's part of it, currently.",
        "start_offset": 27.60000000000001,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      },
      {
        "character": "PAT",
        "text": "Another is because this musician, this artist \u2014 who was already anonymous, as far as I was concerned, before taking the extraordinary step of forsaking me, limiting my access to existing and future content, eternally, online \u2014 doesn't make enough of their music. So, without a doubt, I want to hear more music like that.",
        "start_offset": 32.00000000000001,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      },
      {
        "character": "PAT",
        "text": "...",
        "start_offset": 54.00000000000001,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 13,
    "duration_sec": 33.36363636363637,
    "content": "DOC: What?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "What?",
        "start_offset": 54.400000000000006,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 14,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Like this musician's music, which I loved so much before being forcibly excluded from their lifestyle.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Like this musician's music, which I loved so much before being forcibly excluded from their lifestyle.",
        "start_offset": 54.800000000000004,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 15,
    "duration_sec": 33.36363636363637,
    "content": "DOC: The music is embedded in their lifestyle? Or it's the PERSON you love, and you miss them.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "The music is embedded in their lifestyle? Or it's the PERSON you love, and you miss them.",
        "start_offset": 61.2,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 16,
    "duration_sec": 33.36363636363637,
    "content": "PAT: And still do, and no, just any supplemental material \u2014 posts, likes, updates, and so forth.\nNothing about the person \u2014 though we'll get to that later \u2014 like I said, anonymous.\nBut I can still listen to the old music. That's just IT.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "And still do, and no, just any supplemental material \u2014 posts, likes, updates, and so forth.",
        "start_offset": 68.0,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      },
      {
        "character": "PAT",
        "text": "Nothing about the person \u2014 though we'll get to that later \u2014 like I said, anonymous.",
        "start_offset": 74.4,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      },
      {
        "character": "PAT",
        "text": "But I can still listen to the old music. That's just IT.",
        "start_offset": 80.80000000000001,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 17,
    "duration_sec": 33.36363636363637,
    "content": "DOC: What is?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "What is?",
        "start_offset": 85.60000000000001,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 18,
    "duration_sec": 33.36363636363637,
    "content": "PAT: All there is. All I GET.\nIs one reason.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "All there is. All I GET.",
        "start_offset": 86.4,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      },
      {
        "character": "PAT",
        "text": "Is one reason.",
        "start_offset": 88.80000000000001,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 19,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Can someone like me listen to their work? How would I find it?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Can someone like me listen to their work? How would I find it?",
        "start_offset": 90.00000000000001,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 20,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Well, it's usually spelled one way, i.e., the traditional way.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Well, it's usually spelled one way, i.e., the traditional way.",
        "start_offset": 95.20000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 21,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Mmm.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Mmm.",
        "start_offset": 99.20000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 22,
    "duration_sec": 33.36363636363637,
    "content": "PAT: But if one spelled it one OTHER way \u2014",
    "dialogue": [
      {
        "character": "PAT",
        "text": "But if one spelled it one OTHER way \u2014",
        "start_offset": 99.60000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 23,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Why?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Why?",
        "start_offset": 103.20000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 24,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Exactly.\n[Pause]",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Exactly.",
        "start_offset": 103.60000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      },
      {
        "character": "PAT",
        "text": "...",
        "start_offset": 104.00000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 25,
    "duration_sec": 33.36363636363637,
    "content": "DOC: What?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "What?",
        "start_offset": 104.40000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 26,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Shouldn't have trouble, no.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Shouldn't have trouble, no.",
        "start_offset": 104.80000000000004,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 27,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Mm ... hmm. Well \u2014",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Mm ... hmm. Well \u2014",
        "start_offset": 106.40000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 28,
    "duration_sec": 33.36363636363637,
    "content": "PAT: The other reason is \u2014",
    "dialogue": [
      {
        "character": "PAT",
        "text": "The other reason is \u2014",
        "start_offset": 108.40000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 29,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Sorry, what makes it so good? I mean \u2014 why do you like it so much that you want to, I don't want to say \"counterfeit\" it, but \u2014",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Sorry, what makes it so good? I mean \u2014 why do you like it so much that you want to, I don't want to say \"counterfeit\" it, but \u2014",
        "start_offset": 110.40000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 30,
    "duration_sec": 33.36363636363637,
    "content": "PAT: You can say 'counterfeit.' That's fine, although this is too many questions.\nThat's another reason too, I suppose.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "You can say 'counterfeit.' That's fine, although this is too many questions.",
        "start_offset": 122.00000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      },
      {
        "character": "PAT",
        "text": "That's another reason too, I suppose.",
        "start_offset": 126.80000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 31,
    "duration_sec": 33.36363636363637,
    "content": "DOC: The one you were about to say.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "The one you were about to say.",
        "start_offset": 129.20000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 32,
    "duration_sec": 33.36363636363637,
    "content": "PAT: No.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "No.",
        "start_offset": 132.00000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 33,
    "duration_sec": 33.36363636363637,
    "content": "DOC: OK.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "OK.",
        "start_offset": 132.40000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 34,
    "duration_sec": 33.36363636363637,
    "content": "PAT: There's too many reasons.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "There's too many reasons.",
        "start_offset": 132.80000000000004,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 35,
    "duration_sec": 33.36363636363637,
    "content": "DOC: We've got plenty of time.\n[Pause]",
    "dialogue": [
      {
        "character": "DOC",
        "text": "We've got plenty of time.",
        "start_offset": 134.40000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      },
      {
        "character": "DOC",
        "text": "...",
        "start_offset": 136.40000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 36,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Almost undeniably, there is an interest in convincing, or even fooling, myself \u2014 not to mention others who may also crave this sort of thing, and not know why, or how to do it \u2014 into believing that the original music I produce and distribute to the world, all of my fabulous music in this brand new zombie musical \u2014 which is also a comedy, even though the music isn't funny, but we'll talk more about that in a minute, if there's time \u2014 is like a dream come true, finally.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Almost undeniably, there is an interest in convincing, or even fooling, myself \u2014 not to mention others who may also crave this sort of thing, and not know why, or how to do it \u2014 into believing that the original music I produce and distribute to the world, all of my fabulous music in this brand new zombie musical \u2014 which is also a comedy, even though the music isn't funny, but we'll talk more about that in a minute, if there's time \u2014 is like a dream come true, finally.",
        "start_offset": 136.80000000000004,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 37,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Alright. Well, how\u2014",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Alright. Well, how\u2014",
        "start_offset": 173.20000000000005,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 38,
    "duration_sec": 33.36363636363637,
    "content": "PAT: More, more, so much more of what I've always wanted, at least for the past ten years or so, that I can hardly handle it or stand it at all and it just keeps coming, and that threatens to devalue it even though it's so good and fun to listen to and useful, but then luckily it ends and it's not like it just went on forever, which was the fear at a certain point, but it's something you could have gotten used to if it had come down to that. So yeah, nothing \u2014 to be AFRAID, of any more.\n[Pause]",
    "dialogue": [
      {
        "character": "PAT",
        "text": "More, more, so much more of what I've always wanted, at least for the past ten years or so, that I can hardly handle it or stand it at all and it just keeps coming, and that threatens to devalue it even though it's so good and fun to listen to and useful, but then luckily it ends and it's not like it just went on forever, which was the fear at a certain point, but it's something you could have gotten used to if it had come down to that. So yeah, nothing \u2014 to be AFRAID, of any more.",
        "start_offset": 174.40000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      },
      {
        "character": "PAT",
        "text": "...",
        "start_offset": 214.80000000000004,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 39,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Scary!",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Scary!",
        "start_offset": 215.20000000000005,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 40,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Perhaps it's just me, but I long to produce that sort of work, enable that sort of experience, and elicit that sort of reaction from an audience, whenever they encounter and finally realize what I've done.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Perhaps it's just me, but I long to produce that sort of work, enable that sort of experience, and elicit that sort of reaction from an audience, whenever they encounter and finally realize what I've done.",
        "start_offset": 215.60000000000005,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 0
      }
    ]
  },
  {
    "id": 41,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Wow.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Wow.",
        "start_offset": 230.00000000000006,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 1
      }
    ]
  },
  {
    "id": 42,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Yeah. It's pretty unbearable.\nBut the other one I was going to say was just to try, you know, to try to use the skills and tools I have or have developed to make a work of art, a good one, or I guess something, an object which expresses something, a communication that is crucially me or mine to express, and which I WANT to express, that I think is valuable to transmit to the world at large, and which other people may also therefore enjoy.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Yeah. It's pretty unbearable.",
        "start_offset": 230.40000000000006,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 2
      },
      {
        "character": "PAT",
        "text": "But the other one I was going to say was just to try, you know, to try to use the skills and tools I have or have developed to make a work of art, a good one, or I guess something, an object which expresses something, a communication that is crucially me or mine to express, and which I WANT to express, that I think is valuable to transmit to the world at large, and which other people may also therefore enjoy.",
        "start_offset": 232.00000000000006,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 3
      }
    ]
  },
  {
    "id": 43,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Therefore?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Therefore?",
        "start_offset": 264.80000000000007,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 4
      }
    ]
  },
  {
    "id": 44,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Meaning, as a serially consequent result of my self-assessed importance of thought.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Meaning, as a serially consequent result of my self-assessed importance of thought.",
        "start_offset": 265.20000000000005,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 5
      }
    ]
  },
  {
    "id": 45,
    "duration_sec": 33.36363636363637,
    "content": "DOC: That's where, I think, you lost me.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "That's where, I think, you lost me.",
        "start_offset": 270.00000000000006,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 6
      }
    ]
  },
  {
    "id": 46,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Yeah. Well, that's not really, you know, part of the deal. My reasons can be incomplete, or wrong-headed, or even terrible.\nI didn't have to say that thing about other people enjoying it at all.\n[A muffled scream in the distance]",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Yeah. Well, that's not really, you know, part of the deal. My reasons can be incomplete, or wrong-headed, or even terrible.",
        "start_offset": 272.80000000000007,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 7
      },
      {
        "character": "PAT",
        "text": "I didn't have to say that thing about other people enjoying it at all.",
        "start_offset": 281.20000000000005,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 8
      },
      {
        "character": "PAT",
        "text": "...",
        "start_offset": 286.80000000000007,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 9
      }
    ]
  },
  {
    "id": 47,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I was afraid of that.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I was afraid of that.",
        "start_offset": 287.20000000000005,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 10
      }
    ]
  },
  {
    "id": 48,
    "duration_sec": 33.36363636363637,
    "content": "PAT: It's nothing to be afraid. Of COURSE, life is scary, but this isn't the autumn masque and bonfire ceremony. We're not trying to emphasize our cruelest aspects, or even reconcile them.\nIt's just art, baby, freed from commerce and all its pressures.\nFree of life.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "It's nothing to be afraid. Of COURSE, life is scary, but this isn't the autumn masque and bonfire ceremony. We're not trying to emphasize our cruelest aspects, or even reconcile them.",
        "start_offset": 289.20000000000005,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 11
      },
      {
        "character": "PAT",
        "text": "It's just art, baby, freed from commerce and all its pressures.",
        "start_offset": 301.6,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 12
      },
      {
        "character": "PAT",
        "text": "Free of life.",
        "start_offset": 306.0,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 13
      }
    ]
  },
  {
    "id": 49,
    "duration_sec": 33.36363636363637,
    "content": "DOC: And more than likely, free of charge.\nApologies \u2014 that's a bad, not to mention seriously discouraging, joke.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "And more than likely, free of charge.",
        "start_offset": 307.2,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 14
      },
      {
        "character": "DOC",
        "text": "Apologies \u2014 that's a bad, not to mention seriously discouraging, joke.",
        "start_offset": 310.0,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 15
      }
    ]
  },
  {
    "id": 50,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Remember, it's also a bit of a comedy.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Remember, it's also a bit of a comedy.",
        "start_offset": 314.4,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 16
      }
    ]
  },
  {
    "id": 51,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I'm sorry.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I'm sorry.",
        "start_offset": 317.59999999999997,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 17
      }
    ]
  },
  {
    "id": 52,
    "duration_sec": 33.36363636363637,
    "content": "PAT: But no, for real ... you think people would pay MONEY to see something like this?",
    "dialogue": [
      {
        "character": "PAT",
        "text": "But no, for real ... you think people would pay MONEY to see something like this?",
        "start_offset": 318.4,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 18
      }
    ]
  },
  {
    "id": 53,
    "duration_sec": 33.36363636363637,
    "content": "DOC: How does it look?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "How does it look?",
        "start_offset": 324.79999999999995,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 19
      }
    ]
  },
  {
    "id": 54,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Listen to it, then.\n[Pause]",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Listen to it, then.",
        "start_offset": 326.4,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 20
      },
      {
        "character": "PAT",
        "text": "...",
        "start_offset": 328.0,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 21
      }
    ]
  },
  {
    "id": 55,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I'm not sure what I'm listening for, but I would pay for this, sure.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I'm not sure what I'm listening for, but I would pay for this, sure.",
        "start_offset": 328.4,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 22
      }
    ]
  },
  {
    "id": 56,
    "duration_sec": 33.36363636363637,
    "content": "PAT: You would?",
    "dialogue": [
      {
        "character": "PAT",
        "text": "You would?",
        "start_offset": 334.0,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 23
      }
    ]
  },
  {
    "id": 57,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I mean, no. If I was a PERSON. It might be a conflict of interest anyway.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I mean, no. If I was a PERSON. It might be a conflict of interest anyway.",
        "start_offset": 334.8,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 24
      }
    ]
  },
  {
    "id": 58,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Conflict of \u2014 horse puckey. You don't like it, that's what's going on.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Conflict of \u2014 horse puckey. You don't like it, that's what's going on.",
        "start_offset": 341.2,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 25
      }
    ]
  },
  {
    "id": 59,
    "duration_sec": 33.36363636363637,
    "content": "DOC: [Looking at watch] You know what, shoot. I have something else I've committed, uh \u2014 I'm booked solid.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "[Looking at watch] You know what, shoot. I have something else I've committed, uh \u2014 I'm booked solid.",
        "start_offset": 346.4,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 26
      }
    ]
  },
  {
    "id": 60,
    "duration_sec": 33.36363636363637,
    "content": "PAT: You don't have to lie to me, or make up excuses.\nIt's just an idea, something I could do. Maybe it's a bad idea.\nMaybe I shouldn't do it, even if I DO fully believe it's gorgeous and needs to be shared with the world to improve everybody's quality of life.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "You don't have to lie to me, or make up excuses.",
        "start_offset": 353.59999999999997,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 27
      },
      {
        "character": "PAT",
        "text": "It's just an idea, something I could do. Maybe it's a bad idea.",
        "start_offset": 357.99999999999994,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 28
      },
      {
        "character": "PAT",
        "text": "Maybe I shouldn't do it, even if I DO fully believe it's gorgeous and needs to be shared with the world to improve everybody's quality of life.",
        "start_offset": 363.19999999999993,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 29
      }
    ]
  },
  {
    "id": 61,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Do you really think that?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Do you really think that?",
        "start_offset": 373.99999999999994,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 30
      }
    ]
  },
  {
    "id": 62,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Of course I do. I'm an artist.\nThere's no LIMIT to the bullshit I can think about.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Of course I do. I'm an artist.",
        "start_offset": 375.99999999999994,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 31
      },
      {
        "character": "PAT",
        "text": "There's no LIMIT to the bullshit I can think about.",
        "start_offset": 378.79999999999995,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 32
      }
    ]
  },
  {
    "id": 63,
    "duration_sec": 33.36363636363637,
    "content": "DOC: But what if you're wrong?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "But what if you're wrong?",
        "start_offset": 382.79999999999995,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 33
      }
    ]
  },
  {
    "id": 64,
    "duration_sec": 33.36363636363637,
    "content": "PAT: What if I was RIGHT? That's the scary one, pal.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "What if I was RIGHT? That's the scary one, pal.",
        "start_offset": 384.79999999999995,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 34
      }
    ]
  },
  {
    "id": 65,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Why does that scare you?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Why does that scare you?",
        "start_offset": 388.79999999999995,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 35
      }
    ]
  },
  {
    "id": 66,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Why does everything. Look, I'll ask the questions here.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Why does everything. Look, I'll ask the questions here.",
        "start_offset": 390.79999999999995,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 36
      }
    ]
  },
  {
    "id": 67,
    "duration_sec": 33.36363636363637,
    "content": "DOC: That's not the way it usually works.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "That's not the way it usually works.",
        "start_offset": 394.4,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 37
      }
    ]
  },
  {
    "id": 68,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Maybe I'm one of a kind. Maybe I'm one in a million!",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Maybe I'm one of a kind. Maybe I'm one in a million!",
        "start_offset": 397.2,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 38
      }
    ]
  },
  {
    "id": 69,
    "duration_sec": 33.36363636363637,
    "content": "DOC: We all are.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "We all are.",
        "start_offset": 402.0,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 39
      }
    ]
  },
  {
    "id": 70,
    "duration_sec": 33.36363636363637,
    "content": "PAT: That wasn't a question. But it reminded me, another reason is, there's another album, by another artist, that I think I want to emulate and this sounds like too.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "That wasn't a question. But it reminded me, another reason is, there's another album, by another artist, that I think I want to emulate and this sounds like too.",
        "start_offset": 403.2,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 40
      }
    ]
  },
  {
    "id": 71,
    "duration_sec": 33.36363636363637,
    "content": "DOC: [Sighs] And how did THIS anonymous musician wrong you?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "[Sighs] And how did THIS anonymous musician wrong you?",
        "start_offset": 414.8,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 41
      }
    ]
  },
  {
    "id": 72,
    "duration_sec": 33.36363636363637,
    "content": "PAT: I can't believe you would actually sigh.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "I can't believe you would actually sigh.",
        "start_offset": 418.40000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 42
      }
    ]
  },
  {
    "id": 73,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Like I said, we're all human.\nWe have to breathe, and sometimes we build up an excess.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Like I said, we're all human.",
        "start_offset": 421.20000000000005,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 43
      },
      {
        "character": "DOC",
        "text": "We have to breathe, and sometimes we build up an excess.",
        "start_offset": 423.6,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 44
      }
    ]
  },
  {
    "id": 74,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Is that what does it?",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Is that what does it?",
        "start_offset": 428.0,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 45
      }
    ]
  },
  {
    "id": 75,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Not surprising you wouldn't know.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Not surprising you wouldn't know.",
        "start_offset": 430.0,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 46
      }
    ]
  },
  {
    "id": 76,
    "duration_sec": 33.36363636363637,
    "content": "PAT: I forget. But it's not always about being wronged.\nLike I believe I've alluded to, it's about trying to reproduce or otherwise live up to the things I like, and which other people seem to like as well as me.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "I forget. But it's not always about being wronged.",
        "start_offset": 432.0,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 47
      },
      {
        "character": "PAT",
        "text": "Like I believe I've alluded to, it's about trying to reproduce or otherwise live up to the things I like, and which other people seem to like as well as me.",
        "start_offset": 435.6,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 48
      }
    ]
  },
  {
    "id": 77,
    "duration_sec": 33.36363636363637,
    "content": "DOC: An ideal.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "An ideal.",
        "start_offset": 448.0,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 49
      }
    ]
  },
  {
    "id": 78,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Excuse me?",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Excuse me?",
        "start_offset": 448.8,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 50
      }
    ]
  },
  {
    "id": 79,
    "duration_sec": 33.36363636363637,
    "content": "DOC: That's what we like to live up to. I'm trying to avoid questioning, the way you asked.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "That's what we like to live up to. I'm trying to avoid questioning, the way you asked.",
        "start_offset": 449.6,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 51
      }
    ]
  },
  {
    "id": 80,
    "duration_sec": 33.36363636363637,
    "content": "PAT: I don't think these are ideals. I don't think there's some ... apotheosis.\nOr if there is, it's not what I'm striving towards.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "I don't think these are ideals. I don't think there's some ... apotheosis.",
        "start_offset": 456.40000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 52
      },
      {
        "character": "PAT",
        "text": "Or if there is, it's not what I'm striving towards.",
        "start_offset": 461.6,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 53
      }
    ]
  },
  {
    "id": 81,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I just thought your choice of words was interesting.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I just thought your choice of words was interesting.",
        "start_offset": 465.6,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 54
      }
    ]
  },
  {
    "id": 82,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Me too! Yet ANOTHER reason.\nI believe I'm good at writing \u2014 word choices, of course, in addition to music notes, I guess. But sure, there's a certain element of needing to live up to my parents' ideas, about me writing a comedy musical.\nThat's not the primary motivator, I don't think, but it's in the mix, even though they may not like it at all.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Me too! Yet ANOTHER reason.",
        "start_offset": 469.20000000000005,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 55
      },
      {
        "character": "PAT",
        "text": "I believe I'm good at writing \u2014 word choices, of course, in addition to music notes, I guess. But sure, there's a certain element of needing to live up to my parents' ideas, about me writing a comedy musical.",
        "start_offset": 471.20000000000005,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 56
      },
      {
        "character": "PAT",
        "text": "That's not the primary motivator, I don't think, but it's in the mix, even though they may not like it at all.",
        "start_offset": 486.80000000000007,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 57
      }
    ]
  },
  {
    "id": 83,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I wasn't \u2014",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I wasn't \u2014",
        "start_offset": 495.6000000000001,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 58
      }
    ]
  },
  {
    "id": 84,
    "duration_sec": 33.36363636363637,
    "content": "PAT: It's fine. It might even be my projection of what they want. It's not real pressure.\nThey'll appreciate that I'm happy with the end product, if I am, and I can't imagine I won't be.\nEverybody has a variety of purposes for their life.\nEveryone has a dozen or so reasons, maybe more.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "It's fine. It might even be my projection of what they want. It's not real pressure.",
        "start_offset": 496.80000000000007,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 59
      },
      {
        "character": "PAT",
        "text": "They'll appreciate that I'm happy with the end product, if I am, and I can't imagine I won't be.",
        "start_offset": 503.20000000000005,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 60
      },
      {
        "character": "PAT",
        "text": "Everybody has a variety of purposes for their life.",
        "start_offset": 510.80000000000007,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 61
      },
      {
        "character": "PAT",
        "text": "Everyone has a dozen or so reasons, maybe more.",
        "start_offset": 514.4000000000001,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 62
      }
    ]
  },
  {
    "id": 85,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Absolutely, uh, sure.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Absolutely, uh, sure.",
        "start_offset": 518.0000000000001,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 63
      }
    ]
  },
  {
    "id": 86,
    "duration_sec": 33.36363636363637,
    "content": "PAT: So I should do it?",
    "dialogue": [
      {
        "character": "PAT",
        "text": "So I should do it?",
        "start_offset": 519.2000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 64
      }
    ]
  },
  {
    "id": 87,
    "duration_sec": 33.36363636363637,
    "content": "DOC: That's not ... ultimately, it's up to you. You certainly seem to have your mind set on it, along with a good number of other things ... going on.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "That's not ... ultimately, it's up to you. You certainly seem to have your mind set on it, along with a good number of other things ... going on.",
        "start_offset": 521.2000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 65
      }
    ]
  },
  {
    "id": 88,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Are you superstitious?",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Are you superstitious?",
        "start_offset": 532.8000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 66
      }
    ]
  },
  {
    "id": 89,
    "duration_sec": 33.36363636363637,
    "content": "DOC: A little bit.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "A little bit.",
        "start_offset": 534.0000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 67
      }
    ]
  },
  {
    "id": 90,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Because there are a few more.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Because there are a few more.",
        "start_offset": 535.2000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 68
      }
    ]
  },
  {
    "id": 91,
    "duration_sec": 33.36363636363637,
    "content": "DOC: You know, you don't have to convince me. Unless \u2014",
    "dialogue": [
      {
        "character": "DOC",
        "text": "You know, you don't have to convince me. Unless \u2014",
        "start_offset": 537.6000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 69
      }
    ]
  },
  {
    "id": 92,
    "duration_sec": 33.36363636363637,
    "content": "PAT: This isn't about money, or promotional word of mouth, or any other sort of hustle. I just want to make a zombie musical that isn't too funny, and this is the way I'm going to do it.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "This isn't about money, or promotional word of mouth, or any other sort of hustle. I just want to make a zombie musical that isn't too funny, and this is the way I'm going to do it.",
        "start_offset": 541.6000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 70
      }
    ]
  },
  {
    "id": 93,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Well that's that settled, then! But seriously though, now that you've resolved to do it, how do \u2014",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Well that's that settled, then! But seriously though, now that you've resolved to do it, how do \u2014",
        "start_offset": 556.4000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 71
      }
    ]
  },
  {
    "id": 94,
    "duration_sec": 33.36363636363637,
    "content": "PAT: The artist's music is silent.\n[Pause]\nMost successful musicals are not silent \u2014 or if many are, I'm not familiar with them. So they have to be successful solely on a small scale, what's called a 'nietszch demographic.'\nThis has never been common knowledge before, which actually makes it one of the more compelling reasons for you to produce the show. It's possible for a musical to be successful in the current era even if it only appeals to a staggeringly small number of audience members, as it turns out. Which\u2014",
    "dialogue": [
      {
        "character": "PAT",
        "text": "The artist's music is silent.",
        "start_offset": 563.6000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 72
      },
      {
        "character": "PAT",
        "text": "...",
        "start_offset": 565.6000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 73
      },
      {
        "character": "PAT",
        "text": "Most successful musicals are not silent \u2014 or if many are, I'm not familiar with them. So they have to be successful solely on a small scale, what's called a 'nietszch demographic.'",
        "start_offset": 566.0000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 74
      },
      {
        "character": "PAT",
        "text": "This has never been common knowledge before, which actually makes it one of the more compelling reasons for you to produce the show. It's possible for a musical to be successful in the current era even if it only appeals to a staggeringly small number of audience members, as it turns out. Which\u2014",
        "start_offset": 578.8000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 75
      }
    ]
  },
  {
    "id": 95,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I'm sorry. The musical is silent?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I'm sorry. The musical is silent?",
        "start_offset": 600.0000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 76
      }
    ]
  },
  {
    "id": 96,
    "duration_sec": 33.36363636363637,
    "content": "PAT: There aren't any word notes, or 'lyrics.' I believe it's called a book, or it would be.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "There aren't any word notes, or 'lyrics.' I believe it's called a book, or it would be.",
        "start_offset": 602.4000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 77
      }
    ]
  },
  {
    "id": 97,
    "duration_sec": 33.36363636363637,
    "content": "DOC: So it's just ... a BOOK, then? But WITHOUT any lyrics, or ... footnotes?\nForgive me for being confused. Also, I'm not really available, or able, to produce anything \u2014 musical shows, wordless books, or otherwise. Sorry if I've misrepresented myself.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "So it's just ... a BOOK, then? But WITHOUT any lyrics, or ... footnotes?",
        "start_offset": 609.2000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 78
      },
      {
        "character": "DOC",
        "text": "Forgive me for being confused. Also, I'm not really available, or able, to produce anything \u2014 musical shows, wordless books, or otherwise. Sorry if I've misrepresented myself.",
        "start_offset": 614.8000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 79
      }
    ]
  },
  {
    "id": 98,
    "duration_sec": 33.36363636363637,
    "content": "PAT: No, no, that's fine \u2014 but the BOOK, that's what there WOULD be, in a more typical musical.\nWhat THIS is. But obviously there's music too.\nIt's just silent.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "No, no, that's fine \u2014 but the BOOK, that's what there WOULD be, in a more typical musical.",
        "start_offset": 625.6000000000001,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 80
      },
      {
        "character": "PAT",
        "text": "What THIS is. But obviously there's music too.",
        "start_offset": 632.8000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 81
      },
      {
        "character": "PAT",
        "text": "It's just silent.",
        "start_offset": 636.0000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 82
      }
    ]
  },
  {
    "id": 99,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Oh ... kay. I suppose that IS rather unusual. I must admit, I haven't heard of anything like THAT!",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Oh ... kay. I suppose that IS rather unusual. I must admit, I haven't heard of anything like THAT!",
        "start_offset": 637.2000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 83
      }
    ]
  },
  {
    "id": 100,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Well, it's an emerging market \u2014 but then again, you haven't even heard of the world-famous celebrity artist who inspired me, by viciously cancelling my personal user experience on social media, and in the public square no less.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Well, it's an emerging market \u2014 but then again, you haven't even heard of the world-famous celebrity artist who inspired me, by viciously cancelling my personal user experience on social media, and in the public square no less.",
        "start_offset": 644.8000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 84
      }
    ]
  },
  {
    "id": 101,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Hang on. You were cancelled, publicly?\n[Nervously] Was there ... a conviction?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Hang on. You were cancelled, publicly?",
        "start_offset": 660.0000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 85
      },
      {
        "character": "DOC",
        "text": "[Nervously] Was there ... a conviction?",
        "start_offset": 662.4000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 86
      }
    ]
  },
  {
    "id": 102,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Basically.\nDue to a series of comments I made, and strong convictions on both sides, absolutely. Logistics-wise, I was BLOCKED.\nStill am! I made sure, just now, right before I decided to come here and begin recording the musical with you.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Basically.",
        "start_offset": 664.8000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 87
      },
      {
        "character": "PAT",
        "text": "Due to a series of comments I made, and strong convictions on both sides, absolutely. Logistics-wise, I was BLOCKED.",
        "start_offset": 665.2000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 88
      },
      {
        "character": "PAT",
        "text": "Still am! I made sure, just now, right before I decided to come here and begin recording the musical with you.",
        "start_offset": 672.8000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 89
      }
    ]
  },
  {
    "id": 103,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Oh, uh, good. Not to diminish your personal experience, but I thought we were maybe talkin' a LEGAL thing, which \u2014 well, it would have altered my, um, approach.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Oh, uh, good. Not to diminish your personal experience, but I thought we were maybe talkin' a LEGAL thing, which \u2014 well, it would have altered my, um, approach.",
        "start_offset": 681.2000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 90
      }
    ]
  },
  {
    "id": 104,
    "duration_sec": 33.36363636363637,
    "content": "PAT: You couldn't possibly diminish my experience.\nI can do and decide to perceive anything I want, and then use that as inspiration to make music, musicals, memoirs \u2014 anything, really.\nYou can't stop me.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "You couldn't possibly diminish my experience.",
        "start_offset": 692.8000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 91
      },
      {
        "character": "PAT",
        "text": "I can do and decide to perceive anything I want, and then use that as inspiration to make music, musicals, memoirs \u2014 anything, really.",
        "start_offset": 695.2000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 92
      },
      {
        "character": "PAT",
        "text": "You can't stop me.",
        "start_offset": 704.8000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 93
      }
    ]
  },
  {
    "id": 105,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I'm not trying to.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I'm not trying to.",
        "start_offset": 706.4000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 94
      }
    ]
  },
  {
    "id": 106,
    "duration_sec": 33.36363636363637,
    "content": "PAT: It's fine. You can try if you want. Try super hard, I don't care at all.\nThat's probably one of the most straightforward reasons, honestly.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "It's fine. You can try if you want. Try super hard, I don't care at all.",
        "start_offset": 708.0000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 95
      },
      {
        "character": "PAT",
        "text": "That's probably one of the most straightforward reasons, honestly.",
        "start_offset": 714.4000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 96
      }
    ]
  },
  {
    "id": 107,
    "duration_sec": 33.36363636363637,
    "content": "DOC: To try?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "To try?",
        "start_offset": 718.0000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 97
      }
    ]
  },
  {
    "id": 108,
    "duration_sec": 33.36363636363637,
    "content": "PAT: To combat all the people seeking to strike me down, cancel and block me, report or impede my stride. To produce a fortification, which also works operationally as a weapon on the field of battle.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "To combat all the people seeking to strike me down, cancel and block me, report or impede my stride. To produce a fortification, which also works operationally as a weapon on the field of battle.",
        "start_offset": 718.8000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 98
      }
    ]
  },
  {
    "id": 109,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Jesus Christ.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Jesus Christ.",
        "start_offset": 732.8000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 99
      }
    ]
  },
  {
    "id": 110,
    "duration_sec": 33.36363636363637,
    "content": "PAT: That reminds me. There's ANOTHER album that I want to plagiarize, but that one is a lot sadder, so it's not a very important reason.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "That reminds me. There's ANOTHER album that I want to plagiarize, but that one is a lot sadder, so it's not a very important reason.",
        "start_offset": 733.6000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 100
      }
    ]
  },
  {
    "id": 111,
    "duration_sec": 33.36363636363637,
    "content": "DOC: [Facetiously] Well THAT'S fortunate, at least.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "[Facetiously] Well THAT'S fortunate, at least.",
        "start_offset": 743.6000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 101
      }
    ]
  },
  {
    "id": 112,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Yeah.\nIt's actually doubly sad, because I kind of want to make fun of it. Don't tell anyone.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Yeah.",
        "start_offset": 746.0000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 102
      },
      {
        "character": "PAT",
        "text": "It's actually doubly sad, because I kind of want to make fun of it. Don't tell anyone.",
        "start_offset": 746.4000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 103
      }
    ]
  },
  {
    "id": 113,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I can't imagine I would. But I thought you said the music wasn't funny?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I can't imagine I would. But I thought you said the music wasn't funny?",
        "start_offset": 753.2000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 104
      }
    ]
  },
  {
    "id": 114,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Yeah. Let's talk about that.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Yeah. Let's talk about that.",
        "start_offset": 758.8000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 105
      }
    ]
  },
  {
    "id": 115,
    "duration_sec": 33.36363636363637,
    "content": "DOC: OK. [Hangs head]",
    "dialogue": [
      {
        "character": "DOC",
        "text": "OK. [Hangs head]",
        "start_offset": 760.8000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 106
      }
    ]
  },
  {
    "id": 116,
    "duration_sec": 33.36363636363637,
    "content": "PAT: [Totally not noticing anymore] It needs to be RIGHT in the sweet spot. It needs to be just short of actually, you know, GOOD.\nBut it also needs to have verisimilitude, and since I believe the artist's work is good, there's\u2014",
    "dialogue": [
      {
        "character": "PAT",
        "text": "[Totally not noticing anymore] It needs to be RIGHT in the sweet spot. It needs to be just short of actually, you know, GOOD.",
        "start_offset": 762.0000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 107
      },
      {
        "character": "PAT",
        "text": "But it also needs to have verisimilitude, and since I believe the artist's work is good, there's\u2014",
        "start_offset": 771.6000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 108
      }
    ]
  },
  {
    "id": 117,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Which one?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Which one?",
        "start_offset": 778.4000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 109
      }
    ]
  },
  {
    "id": 118,
    "duration_sec": 33.36363636363637,
    "content": "PAT: The main one.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "The main one.",
        "start_offset": 779.2000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 110
      }
    ]
  },
  {
    "id": 119,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Not the other two?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Not the other two?",
        "start_offset": 780.4000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 111
      }
    ]
  },
  {
    "id": 120,
    "duration_sec": 33.36363636363637,
    "content": "PAT: There are actually three other ones \u2014 people reasons, that is. And they're all GREAT, you should definitely give them ALL a shot if you can.\nBut never mind that. How do you think we'll be able to tell if we find that sweet spot?",
    "dialogue": [
      {
        "character": "PAT",
        "text": "There are actually three other ones \u2014 people reasons, that is. And they're all GREAT, you should definitely give them ALL a shot if you can.",
        "start_offset": 782.0000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 112
      },
      {
        "character": "PAT",
        "text": "But never mind that. How do you think we'll be able to tell if we find that sweet spot?",
        "start_offset": 792.4000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 113
      }
    ]
  },
  {
    "id": 121,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I have no idea.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I have no idea.",
        "start_offset": 800.0000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 114
      }
    ]
  },
  {
    "id": 122,
    "duration_sec": 33.36363636363637,
    "content": "PAT: It can't be too funny.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "It can't be too funny.",
        "start_offset": 801.6000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 115
      }
    ]
  },
  {
    "id": 123,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Yeah, I doubt it.\n[Pause]\nAren't there other things you could do with all this energy?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Yeah, I doubt it.",
        "start_offset": 803.6000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 116
      },
      {
        "character": "DOC",
        "text": "...",
        "start_offset": 805.2000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 117
      },
      {
        "character": "DOC",
        "text": "Aren't there other things you could do with all this energy?",
        "start_offset": 805.6000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 118
      }
    ]
  },
  {
    "id": 124,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Obviously, yes, of course. And I'm doing those things too.\nSometimes, people get a desire like this, and they chase it for a while, but ultimately just have to abandon it in favor of other priorities. So it doesn't hurt to stack 'em up.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Obviously, yes, of course. And I'm doing those things too.",
        "start_offset": 810.0000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 119
      },
      {
        "character": "PAT",
        "text": "Sometimes, people get a desire like this, and they chase it for a while, but ultimately just have to abandon it in favor of other priorities. So it doesn't hurt to stack 'em up.",
        "start_offset": 814.0000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 120
      }
    ]
  },
  {
    "id": 125,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I can't recall anything like that ever happening to anyone I know.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I can't recall anything like that ever happening to anyone I know.",
        "start_offset": 827.6000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 121
      }
    ]
  },
  {
    "id": 126,
    "duration_sec": 33.36363636363637,
    "content": "PAT: And maybe I will. But for now, I'm following the vein, as it were, and going ahead and recording it with you.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "And maybe I will. But for now, I'm following the vein, as it were, and going ahead and recording it with you.",
        "start_offset": 832.4000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 122
      }
    ]
  },
  {
    "id": 127,
    "duration_sec": 33.36363636363637,
    "content": "DOC: [Laughs nervously] I'm not sure I'm the right one to solve all, or even any, of your admittedly interesting-to-you problems!",
    "dialogue": [
      {
        "character": "DOC",
        "text": "[Laughs nervously] I'm not sure I'm the right one to solve all, or even any, of your admittedly interesting-to-you problems!",
        "start_offset": 841.2000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 123
      }
    ]
  },
  {
    "id": 128,
    "duration_sec": 33.36363636363637,
    "content": "PAT: You've already helped so much, though. I couldn't do it without you.\nSeriously \u2014 you GOT this. Anything I can do to make it more fun?\n[Pause]",
    "dialogue": [
      {
        "character": "PAT",
        "text": "You've already helped so much, though. I couldn't do it without you.",
        "start_offset": 849.2000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 124
      },
      {
        "character": "PAT",
        "text": "Seriously \u2014 you GOT this. Anything I can do to make it more fun?",
        "start_offset": 854.0000000000001,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 125
      },
      {
        "character": "PAT",
        "text": "...",
        "start_offset": 859.6000000000001,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 126
      }
    ]
  },
  {
    "id": 129,
    "duration_sec": 33.36363636363637,
    "content": "DOC: [Sighs even more dramatically] I'm just not sure I understand what you WANT.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "[Sighs even more dramatically] I'm just not sure I understand what you WANT.",
        "start_offset": 860.0000000000001,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 127
      }
    ]
  },
  {
    "id": 130,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Careful, it might become a catchphrase and you'll suffocate yourself.\n[Chuckles] Kidding.\nWhich reasons are you getting hung up on? The artist whom wronged me horribly, or the others, whether sad or glorious, that I seek to emulate, or my various unusual goals I propose to realize through this unrealistic project, combining music and unsung intercommunication, which I call 'silence,' into one single albeit singularly seriously not funny gesamtkunstwerk of melodic theater and non-musical comedy for the masses around the world to criticize and enjoy?\n[Pause]",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Careful, it might become a catchphrase and you'll suffocate yourself.",
        "start_offset": 865.2000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 128
      },
      {
        "character": "PAT",
        "text": "[Chuckles] Kidding.",
        "start_offset": 869.2000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 129
      },
      {
        "character": "PAT",
        "text": "Which reasons are you getting hung up on? The artist whom wronged me horribly, or the others, whether sad or glorious, that I seek to emulate, or my various unusual goals I propose to realize through this unrealistic project, combining music and unsung intercommunication, which I call 'silence,' into one single albeit singularly seriously not funny gesamtkunstwerk of melodic theater and non-musical comedy for the masses around the world to criticize and enjoy?",
        "start_offset": 870.0000000000001,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 130
      },
      {
        "character": "PAT",
        "text": "...",
        "start_offset": 899.2000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 131
      }
    ]
  },
  {
    "id": 131,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I'm not sure that counts as a gesamtkunstwerk.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I'm not sure that counts as a gesamtkunstwerk.",
        "start_offset": 899.6000000000001,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 132
      }
    ]
  },
  {
    "id": 132,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Oh, but it must, by the standards of the gesamtkunstwerk competition I intend to enter it into once it is complete! Lucky for you, the guidelines are QUITE generous nowadays, if only to drive submission volumes up.\nI can't say much more about that, because the entries need to be anonymous. I'm sure you understand.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Oh, but it must, by the standards of the gesamtkunstwerk competition I intend to enter it into once it is complete! Lucky for you, the guidelines are QUITE generous nowadays, if only to drive submission volumes up.",
        "start_offset": 902.8000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 133
      },
      {
        "character": "PAT",
        "text": "I can't say much more about that, because the entries need to be anonymous. I'm sure you understand.",
        "start_offset": 917.6000000000001,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 134
      }
    ]
  },
  {
    "id": 133,
    "duration_sec": 33.36363636363637,
    "content": "DOC: If anything, LESS than a few minutes ago.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "If anything, LESS than a few minutes ago.",
        "start_offset": 924.8000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 135
      }
    ]
  },
  {
    "id": 134,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Well, if that was the only 'red flag,' my taxonomy criteria \u2014 we should be good to go!\nAnd I agree, this all fits into place and makes sense as a thing we would be doing, and are.\n[Nods furiously]",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Well, if that was the only 'red flag,' my taxonomy criteria \u2014 we should be good to go!",
        "start_offset": 928.0000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 136
      },
      {
        "character": "PAT",
        "text": "And I agree, this all fits into place and makes sense as a thing we would be doing, and are.",
        "start_offset": 935.2000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 137
      },
      {
        "character": "PAT",
        "text": "...",
        "start_offset": 943.2000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 138
      }
    ]
  },
  {
    "id": 135,
    "duration_sec": 33.36363636363637,
    "content": "DOC: So tell me more about this, uh, music, I guess. That should be easy?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "So tell me more about this, uh, music, I guess. That should be easy?",
        "start_offset": 943.6000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 139
      }
    ]
  },
  {
    "id": 136,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Ah, good question! NO, it's NOT easy to explain, much less understand, why I like it so much. And nobody I know will listen to or talk about it with me.\n[Points to music]\nBut if YOU listen closely, I hope, you should be able to identify some of the signatures.\nIt's hypnotic. Repetitive, some might even say, if they ever take me up on it.\nA lot of times, it kind of sounds like a single motif being played with two alternating synth patches, and that's it. It's pretty arrogant music, I reckon.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Ah, good question! NO, it's NOT easy to explain, much less understand, why I like it so much. And nobody I know will listen to or talk about it with me.",
        "start_offset": 949.2000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 140
      },
      {
        "character": "PAT",
        "text": "...",
        "start_offset": 961.6000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 141
      },
      {
        "character": "PAT",
        "text": "But if YOU listen closely, I hope, you should be able to identify some of the signatures.",
        "start_offset": 962.0000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 142
      },
      {
        "character": "PAT",
        "text": "It's hypnotic. Repetitive, some might even say, if they ever take me up on it.",
        "start_offset": 968.8000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 143
      },
      {
        "character": "PAT",
        "text": "A lot of times, it kind of sounds like a single motif being played with two alternating synth patches, and that's it. It's pretty arrogant music, I reckon.",
        "start_offset": 974.8000000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 144
      }
    ]
  },
  {
    "id": 137,
    "duration_sec": 33.36363636363637,
    "content": "DOC: You don't think you're projecting that onto it?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "You don't think you're projecting that onto it?",
        "start_offset": 986.0000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 145
      }
    ]
  },
  {
    "id": 138,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Could be. But I'm also not sure I have to justify my experience of the music, you know?\nEven if I'm wrong, it doesn't change the project.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Could be. But I'm also not sure I have to justify my experience of the music, you know?",
        "start_offset": 989.2000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 146
      },
      {
        "character": "PAT",
        "text": "Even if I'm wrong, it doesn't change the project.",
        "start_offset": 996.4000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 147
      }
    ]
  },
  {
    "id": 139,
    "duration_sec": 33.36363636363637,
    "content": "DOC: How could it not? You have to be sensible about the motivations for your pursuit.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "How could it not? You have to be sensible about the motivations for your pursuit.",
        "start_offset": 1000.0000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 148
      }
    ]
  },
  {
    "id": 140,
    "duration_sec": 33.36363636363637,
    "content": "PAT: I'm being entirely sensible. You can be sensible and still be wrong.\nIt might even lead to better work.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "I'm being entirely sensible. You can be sensible and still be wrong.",
        "start_offset": 1006.0000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 149
      },
      {
        "character": "PAT",
        "text": "It might even lead to better work.",
        "start_offset": 1010.8000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 150
      }
    ]
  },
  {
    "id": 141,
    "duration_sec": 33.36363636363637,
    "content": "DOC: That's certainly an alluring hypothesis.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "That's certainly an alluring hypothesis.",
        "start_offset": 1013.6000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 151
      }
    ]
  },
  {
    "id": 142,
    "duration_sec": 33.36363636363637,
    "content": "PAT: I'm living proof.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "I'm living proof.",
        "start_offset": 1015.6000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 152
      }
    ]
  },
  {
    "id": 143,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I thought you wanted to keep this context-free.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I thought you wanted to keep this context-free.",
        "start_offset": 1016.8000000000003,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 153
      }
    ]
  },
  {
    "id": 144,
    "duration_sec": 33.36363636363637,
    "content": "PAT: I can't omit my entire self. We just won't talk about it.\nLike I said, this artist, the primary one. They're perfectly anonymous, even though their name is public now, it turns out.\nBut I didn't even know that until today, before the session \u2014 and besides, the person, or their human personality, simply CAN'T have any influence on the music's appreciation by the masses, because of their self-induced anonymity. No gossip columnist or Wikipedia editor can change that preference.\nWe, the great herd of unwashed zombies, remain free to enjoy the artistry and historical referenceship of their music, without needing to love or even care about the human being who made it at all, because that's what they have chosen.\nAnd I suppose they doubled down on that choice with me personally. So I get to enjoy it twice as much!",
    "dialogue": [
      {
        "character": "PAT",
        "text": "I can't omit my entire self. We just won't talk about it.",
        "start_offset": 1020.0000000000003,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 154
      },
      {
        "character": "PAT",
        "text": "Like I said, this artist, the primary one. They're perfectly anonymous, even though their name is public now, it turns out.",
        "start_offset": 1024.8000000000004,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 155
      },
      {
        "character": "PAT",
        "text": "But I didn't even know that until today, before the session \u2014 and besides, the person, or their human personality, simply CAN'T have any influence on the music's appreciation by the masses, because of their self-induced anonymity. No gossip columnist or Wikipedia editor can change that preference.",
        "start_offset": 1033.2000000000005,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 156
      },
      {
        "character": "PAT",
        "text": "We, the great herd of unwashed zombies, remain free to enjoy the artistry and historical referenceship of their music, without needing to love or even care about the human being who made it at all, because that's what they have chosen.",
        "start_offset": 1052.0000000000005,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 157
      },
      {
        "character": "PAT",
        "text": "And I suppose they doubled down on that choice with me personally. So I get to enjoy it twice as much!",
        "start_offset": 1068.4000000000005,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 158
      }
    ]
  },
  {
    "id": 145,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Mm-hmm.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Mm-hmm.",
        "start_offset": 1076.8000000000006,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 159
      }
    ]
  },
  {
    "id": 146,
    "duration_sec": 33.36363636363637,
    "content": "PAT: We don't need to talk about me though, or why, anymore, but just trust me, okay? I am at my best when following my instincts and a little unsure of what I'm doing, but having a good time, with a plan in mind.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "We don't need to talk about me though, or why, anymore, but just trust me, okay? I am at my best when following my instincts and a little unsure of what I'm doing, but having a good time, with a plan in mind.",
        "start_offset": 1077.2000000000007,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 160
      }
    ]
  },
  {
    "id": 147,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Right.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Right.",
        "start_offset": 1094.4000000000008,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 161
      }
    ]
  },
  {
    "id": 148,
    "duration_sec": 33.36363636363637,
    "content": "PAT: The best results. And I certainly do!\nClear as day.\nBasically, right now, I'm just wasting precious moments trying to whip out more and more reasons for you, when my mind is already set upon this plan, especially since all of my reasons I can think of involve me again, which inevitably just generates more scum to scrub off it. Ugh!\n[Pause]",
    "dialogue": [
      {
        "character": "PAT",
        "text": "The best results. And I certainly do!",
        "start_offset": 1094.8000000000009,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 162
      },
      {
        "character": "PAT",
        "text": "Clear as day.",
        "start_offset": 1097.6000000000008,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 163
      },
      {
        "character": "PAT",
        "text": "Basically, right now, I'm just wasting precious moments trying to whip out more and more reasons for you, when my mind is already set upon this plan, especially since all of my reasons I can think of involve me again, which inevitably just generates more scum to scrub off it. Ugh!",
        "start_offset": 1098.8000000000009,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 164
      },
      {
        "character": "PAT",
        "text": "...",
        "start_offset": 1119.200000000001,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 165
      }
    ]
  },
  {
    "id": 149,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I'm sorry you feel that way. Glad to help clean up.\nAnd I don't need any more reasons, as I'm sure you're actually aware. Perhaps it helps YOU, to psyche yourself up.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I'm sorry you feel that way. Glad to help clean up.",
        "start_offset": 1119.600000000001,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 166
      },
      {
        "character": "DOC",
        "text": "And I don't need any more reasons, as I'm sure you're actually aware. Perhaps it helps YOU, to psyche yourself up.",
        "start_offset": 1124.0000000000011,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 167
      }
    ]
  },
  {
    "id": 150,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Psyche! You owe me a Coke.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Psyche! You owe me a Coke.",
        "start_offset": 1132.4000000000012,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 168
      }
    ]
  },
  {
    "id": 151,
    "duration_sec": 33.36363636363637,
    "content": "DOC: That's \"jinx.\"",
    "dialogue": [
      {
        "character": "DOC",
        "text": "That's \"jinx.\"",
        "start_offset": 1134.8000000000013,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 169
      }
    ]
  },
  {
    "id": 152,
    "duration_sec": 33.36363636363637,
    "content": "PAT: No, that's when we both say the same word.\n[Pause]",
    "dialogue": [
      {
        "character": "PAT",
        "text": "No, that's when we both say the same word.",
        "start_offset": 1135.6000000000013,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 170
      },
      {
        "character": "PAT",
        "text": "...",
        "start_offset": 1139.2000000000012,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 171
      }
    ]
  },
  {
    "id": 153,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I'll try to remember to get you a Coke.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I'll try to remember to get you a Coke.",
        "start_offset": 1139.6000000000013,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 172
      }
    ]
  },
  {
    "id": 154,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Thanks. But I don't need anything else. I'm good. Really great!\nI AM now realizing, though, that I have to determine how MUCH of myself to scrape or otherwise erase off of it.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Thanks. But I don't need anything else. I'm good. Really great!",
        "start_offset": 1143.2000000000012,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 173
      },
      {
        "character": "PAT",
        "text": "I AM now realizing, though, that I have to determine how MUCH of myself to scrape or otherwise erase off of it.",
        "start_offset": 1147.6000000000013,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 174
      }
    ]
  },
  {
    "id": 155,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Off of what?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Off of what?",
        "start_offset": 1156.4000000000012,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 175
      }
    ]
  },
  {
    "id": 156,
    "duration_sec": 33.36363636363637,
    "content": "PAT: The musical. Obviously, I can say it's by a fake alias or some late-night buffoon, attribution isn't the issue.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "The musical. Obviously, I can say it's by a fake alias or some late-night buffoon, attribution isn't the issue.",
        "start_offset": 1157.6000000000013,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 176
      }
    ]
  },
  {
    "id": 157,
    "duration_sec": 33.36363636363637,
    "content": "DOC: [Impatiently] Tell me the issue.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "[Impatiently] Tell me the issue.",
        "start_offset": 1165.2000000000012,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 177
      }
    ]
  },
  {
    "id": 158,
    "duration_sec": 33.36363636363637,
    "content": "PAT: [Oblivious still] People are going to know it's me, and they're going to be able to see all of my unusual fascinations and decisions in all their glory or whatever the opposite of glory is, with no filter or protection, and I may not be able to hide or escape from their gaze.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "[Oblivious still] People are going to know it's me, and they're going to be able to see all of my unusual fascinations and decisions in all their glory or whatever the opposite of glory is, with no filter or protection, and I may not be able to hide or escape from their gaze.",
        "start_offset": 1167.2000000000012,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 178
      }
    ]
  },
  {
    "id": 159,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Isn't that kind of the point of, you know, art?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Isn't that kind of the point of, you know, art?",
        "start_offset": 1188.4000000000012,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 179
      }
    ]
  },
  {
    "id": 160,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Maybe.\nI mean, no. Which part?",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Maybe.",
        "start_offset": 1192.4000000000012,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 180
      },
      {
        "character": "PAT",
        "text": "I mean, no. Which part?",
        "start_offset": 1192.8000000000013,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 181
      }
    ]
  },
  {
    "id": 161,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Pouring your ideas and own self into a majestic, you know, piece, of \u2014 you said it better, earlier, than I will. But just like, laying yourself bare and expressing something uniquely you.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Pouring your ideas and own self into a majestic, you know, piece, of \u2014 you said it better, earlier, than I will. But just like, laying yourself bare and expressing something uniquely you.",
        "start_offset": 1194.8000000000013,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 182
      }
    ]
  },
  {
    "id": 162,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Oh, totally. I thought you meant the artist being subject to everyone's constant surveillance of their vulnerable naked self as a result of having successfully made a personally meaningful and communicative work of art, or even several.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Oh, totally. I thought you meant the artist being subject to everyone's constant surveillance of their vulnerable naked self as a result of having successfully made a personally meaningful and communicative work of art, or even several.",
        "start_offset": 1208.0000000000014,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 183
      }
    ]
  },
  {
    "id": 163,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I mean, I WASN'T thinking that, but it also sounds pretty accurate. No?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I mean, I WASN'T thinking that, but it also sounds pretty accurate. No?",
        "start_offset": 1222.8000000000013,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 184
      }
    ]
  },
  {
    "id": 164,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Yeah no, it does. Hmm. I guess I need to scrape even MORE of me off this accursed thing, to hedge against constant scrutiny from the world's critics.\nDamn! Just when we were really building up a head of steam.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Yeah no, it does. Hmm. I guess I need to scrape even MORE of me off this accursed thing, to hedge against constant scrutiny from the world's critics.",
        "start_offset": 1228.0000000000014,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 185
      },
      {
        "character": "PAT",
        "text": "Damn! Just when we were really building up a head of steam.",
        "start_offset": 1239.2000000000014,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 186
      }
    ]
  },
  {
    "id": 165,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I'm sorry you sound so disappointed by a thing you seem to have just made up.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I'm sorry you sound so disappointed by a thing you seem to have just made up.",
        "start_offset": 1244.0000000000014,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 187
      }
    ]
  },
  {
    "id": 166,
    "duration_sec": 33.36363636363637,
    "content": "PAT: No, it'll be a good challenge. Frankly, I hate talking about me and my process so much anyway.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "No, it'll be a good challenge. Frankly, I hate talking about me and my process so much anyway.",
        "start_offset": 1250.4000000000015,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 188
      }
    ]
  },
  {
    "id": 167,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I can tell.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I can tell.",
        "start_offset": 1257.6000000000015,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 189
      }
    ]
  },
  {
    "id": 168,
    "duration_sec": 33.36363636363637,
    "content": "PAT: The only issue is ... well, we'll figure that out later.\n[Long pause]",
    "dialogue": [
      {
        "character": "PAT",
        "text": "The only issue is ... well, we'll figure that out later.",
        "start_offset": 1258.8000000000015,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 190
      },
      {
        "character": "PAT",
        "text": "...",
        "start_offset": 1263.2000000000016,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 191
      }
    ]
  },
  {
    "id": 169,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Do you think we \u2014",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Do you think we \u2014",
        "start_offset": 1263.6000000000017,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 192
      }
    ]
  },
  {
    "id": 170,
    "duration_sec": 33.36363636363637,
    "content": "DOC: My God. I was COMPLETELY asleep.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "My God. I was COMPLETELY asleep.",
        "start_offset": 1265.6000000000017,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 193
      }
    ]
  },
  {
    "id": 171,
    "duration_sec": 33.36363636363637,
    "content": "PAT: I warned you that it's hypnotic.\nBut so, it's working? I mean, it's accurate?",
    "dialogue": [
      {
        "character": "PAT",
        "text": "I warned you that it's hypnotic.",
        "start_offset": 1268.0000000000018,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 194
      },
      {
        "character": "PAT",
        "text": "But so, it's working? I mean, it's accurate?",
        "start_offset": 1270.400000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 195
      }
    ]
  },
  {
    "id": 172,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I may have just gotten tired, I guess.\nBut sure. There's ... motifs.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I may have just gotten tired, I guess.",
        "start_offset": 1273.600000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 196
      },
      {
        "character": "DOC",
        "text": "But sure. There's ... motifs.",
        "start_offset": 1276.800000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 197
      }
    ]
  },
  {
    "id": 173,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Yess!",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Yess!",
        "start_offset": 1278.800000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 198
      }
    ]
  },
  {
    "id": 174,
    "duration_sec": 33.36363636363637,
    "content": "DOC: And it certainly has a sort of mood to it. One mood, more or less, or rather exactly.\nSo if this is what that artist you love so much sounds like, well ... it is. [Yawns]",
    "dialogue": [
      {
        "character": "DOC",
        "text": "And it certainly has a sort of mood to it. One mood, more or less, or rather exactly.",
        "start_offset": 1279.200000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 199
      },
      {
        "character": "DOC",
        "text": "So if this is what that artist you love so much sounds like, well ... it is. [Yawns]",
        "start_offset": 1286.4000000000021,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 200
      }
    ]
  },
  {
    "id": 175,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Great. And I'll pass it off as being done by someone else, some unsuspecting rube.\nSomebody like, say, you \u2014 obviously it WON'T be you, but as an example.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Great. And I'll pass it off as being done by someone else, some unsuspecting rube.",
        "start_offset": 1293.6000000000022,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 201
      },
      {
        "character": "PAT",
        "text": "Somebody like, say, you \u2014 obviously it WON'T be you, but as an example.",
        "start_offset": 1299.6000000000022,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 202
      }
    ]
  },
  {
    "id": 176,
    "duration_sec": 33.36363636363637,
    "content": "DOC: [Suddenly fully awake] Please don't.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "[Suddenly fully awake] Please don't.",
        "start_offset": 1305.200000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 203
      }
    ]
  },
  {
    "id": 177,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Yeah, I won't \u2014 God, just a RANDOM example.\nI'll say it's by Big Doggins, for instance.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Yeah, I won't \u2014 God, just a RANDOM example.",
        "start_offset": 1307.200000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 204
      },
      {
        "character": "PAT",
        "text": "I'll say it's by Big Doggins, for instance.",
        "start_offset": 1310.800000000002,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 205
      }
    ]
  },
  {
    "id": 178,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Great.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Great.",
        "start_offset": 1314.000000000002,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 206
      }
    ]
  },
  {
    "id": 179,
    "duration_sec": 33.36363636363637,
    "content": "PAT: I just have to make sure I leave as little as possible on here though, because it's not JUST the name. There are ... fingerprints.\nIt's tough, because I keep talking.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "I just have to make sure I leave as little as possible on here though, because it's not JUST the name. There are ... fingerprints.",
        "start_offset": 1314.4000000000021,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 207
      },
      {
        "character": "PAT",
        "text": "It's tough, because I keep talking.",
        "start_offset": 1324.4000000000021,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 208
      }
    ]
  },
  {
    "id": 180,
    "duration_sec": 33.36363636363637,
    "content": "DOC: It must be.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "It must be.",
        "start_offset": 1326.8000000000022,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 209
      }
    ]
  },
  {
    "id": 181,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Maybe some other topics \u2014 things that aren't me, or what I'm trying to do. You got any good ideas?",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Maybe some other topics \u2014 things that aren't me, or what I'm trying to do. You got any good ideas?",
        "start_offset": 1328.0000000000023,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 210
      }
    ]
  },
