    "id": 182,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Like, in general? My normal life?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Like, in general? My normal life?",
        "start_offset": 1336.0000000000023,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 211
      }
    ]
  },
  {
    "id": 183,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Sure, whichever.",
    "dialogue": [
