        "character": "PAT",
        "text": "Sure, whichever.",
        "start_offset": 1338.4000000000024,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 212
      }
    ]
  },
  {
    "id": 184,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I mean, obviously.\n[Pause]",
    "dialogue": [
