        "start_offset": 2247.6000000000054,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 437
      }
    ]
  },
  {
    "id": 337,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Or not, but if you could just clearly write down the main, um, inspirator, as well as the others \u2014 and I can find those on the popular services, too?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "Or not, but if you could just clearly write down the main, um, inspirator, as well as the others \u2014 and I can find those on the popular services, too?",
        "start_offset": 2248.4000000000055,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 438
      }
    ]
  },
  {
    "id": 338,
    "duration_sec": 33.36363636363637,
    "content": "PAT: [Writing] Focusing on the primary one, though.",
    "dialogue": [
