        "character": "DOC",
        "text": "...",
        "start_offset": 2263.600000000006,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 441
      },
      {
        "character": "DOC",
        "text": "Thanks.",
        "start_offset": 2264.000000000006,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 442
      },
      {
        "character": "DOC",
        "text": "...",
        "start_offset": 2264.400000000006,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 443
