        "character": "PAT",
        "text": "Not the same thing. But no, I love cruel feedback. It's a gift.",
        "start_offset": 2359.200000000006,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 465
      },
      {
        "character": "PAT",
        "text": "Probably my WORST gift, if I'm being interviewed.",
        "start_offset": 2364.400000000006,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 466
      },
      {
        "character": "PAT",
        "text": "You found it, I presume?",
        "start_offset": 2367.600000000006,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 467
      }
    ]
  },
  {
    "id": 347,
    "duration_sec": 33.36363636363637,
    "content": "DOC: I did. Listened to everything. It's a lot to take in, especially all the time.",
    "dialogue": [
      {
        "character": "DOC",
        "text": "I did. Listened to everything. It's a lot to take in, especially all the time.",
        "start_offset": 2369.600000000006,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 468
      }
    ]
  },
  {
    "id": 348,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Thanks.",
    "dialogue": [
