        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 560
      }
    ]
  },
  {
    "id": 405,
    "duration_sec": 33.36363636363637,
    "content": "DOC: What?",
    "dialogue": [
      {
        "character": "DOC",
        "text": "What?",
        "start_offset": 2641.600000000007,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 561
      }
    ]
  },
  {
    "id": 406,
    "duration_sec": 33.36363636363637,
    "content": "PAT: I don't know.\n[Pause]",
    "dialogue": [
