        "character": "PAT",
        "text": "I don't know.",
        "start_offset": 2642.0000000000073,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 562
      },
      {
        "character": "PAT",
        "text": "...",
        "start_offset": 2643.200000000007,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 563
      }
    ]
  },
  {
    "id": 407,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Is it the competition?",
    "dialogue": [
