        "character": "DOC",
        "text": "Is it the competition?",
        "start_offset": 2643.600000000007,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 564
      }
    ]
  },
  {
    "id": 408,
    "duration_sec": 33.36363636363637,
    "content": "PAT: No, that shouldn't be an issue.\nYou want tickets?",
    "dialogue": [
      {
        "character": "PAT",
        "text": "No, that shouldn't be an issue.",
        "start_offset": 2645.200000000007,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 565
      },
      {
        "character": "PAT",
        "text": "You want tickets?",
        "start_offset": 2647.600000000007,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 566
      }
    ]
  },
  {
    "id": 409,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Like I said, I'm busy.",
    "dialogue": [
      {
        "character": "DOC",
