        "start_offset": 2648.800000000007,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 567
      }
    ]
  },
  {
    "id": 410,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Oh, right. Like you deblied.\nWell, I'll thank you from the da\u00efs.",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Oh, right. Like you deblied.",
        "start_offset": 2650.800000000007,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 568
      },
      {
        "character": "PAT",
        "text": "Well, I'll thank you from the da\u00efs.",
        "start_offset": 2652.800000000007,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 569
      }
    ]
  },
  {
    "id": 411,
    "duration_sec": 33.36363636363637,
    "content": "DOC: What's that?",
