  },
  {
    "id": 420,
    "duration_sec": 33.36363636363637,
    "content": "PAT: There is.\n[Pause]",
    "dialogue": [
      {
        "character": "PAT",
        "text": "There is.",
        "start_offset": 2686.0000000000077,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 584
