        "character": "PAT",
        "text": "...",
        "start_offset": 2686.800000000008,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 585
      }
    ]
  },
  {
    "id": 421,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Ready whenever you are.",
    "dialogue": [
