        "character": "PAT",
        "text": "Go ahead then.",
        "start_offset": 2688.800000000008,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 587
      }
    ]
  },
  {
    "id": 423,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Hmm?",
    "dialogue": [
