        "character": "DOC",
        "text": "Hmm?",
        "start_offset": 2690.0000000000077,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 588
      }
    ]
  },
  {
    "id": 424,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Admit it was a prank. The full shaboodle.\n[Pause]",
    "dialogue": [
      {
        "character": "PAT",
        "text": "Admit it was a prank. The full shaboodle.",
