        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 589
      },
      {
        "character": "PAT",
        "text": "...",
        "start_offset": 2693.6000000000076,
        "visual_focus": "PAT",
        "action": "Speaking",
        "page_index": 590
      }
    ]
  },
  {
    "id": 425,
    "duration_sec": 33.36363636363637,
    "content": "DOC: Sorry, are you talking to me?",
    "dialogue": [
