        "character": "DOC",
        "text": "Sorry, are you talking to me?",
        "start_offset": 2694.0000000000077,
        "visual_focus": "DOC",
        "action": "Speaking",
        "page_index": 591
      }
    ]
  },
  {
    "id": 426,
    "duration_sec": 33.36363636363637,
    "content": "PAT: Without a doubt.\n[Pause]",
    "dialogue": [
      {
        "character": "PAT",
